export type Lab = { code: string; capacity: number };

// Rename each key to get<Key> with 'as' and a template literal.
export type Getters<T> = {
  [K in keyof T as `get${Capitalize<K & string>}`]: () => T[K];
};

export function toGetters(lab: Lab): Getters<Lab> {
  return { getCode: () => lab.code, getCapacity: () => lab.capacity };
}

import { toGetters } from '../src/getters.ts';
const g = toGetters({ code: 'BE-201', capacity: 40 });
const code: string = g.getCode();       // renamed key
const cap: number = g.getCapacity();
export { code, cap };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toGetters } from '../src/getters.ts';
test('getters', () => { const g = toGetters({ code: 'BE-201', capacity: 40 }); assert.equal(g.getCode(), 'BE-201'); assert.equal(g.getCapacity(), 40); });

